SELECT FROM repair_order
ORDER BY CASE status WHEN 'PENDING' THEN 1 WHEN 'ASSIGNED' THEN 2 WHEN 'PROCESSING' THEN 3 ELSE 4 END, create_time DESC
LIMIT #{offset}, #{limit}

