title = #{title}, content = #{content}, repair_type = #{repairType}, urgency = #{urgency}, status = #{status}, handler = #{handler}, handler_phone = #{handlerPhone}, assign_time = #{assignTime}, finish_time = #{finishTime}, cost = #{cost}, rating = #{rating}, feedback = #{feedback}, remark = #{remark},
WHERE id = #{id}
